/* 下一班雨 — the page reads window.WX, generated by build-data.mjs from the Open-Meteo responses. */
(() => {
  const WX = window.WX
  if (!WX || !WX.districts?.length) return

  const $ = (sel, root = document) => root.querySelector(sel)
  const $$ = (sel, root = document) => [...root.querySelectorAll(sel)]
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches

  const WORDS = { dry: '无雨', light: '小雨', mid: '中雨', heavy: '大雨', storm: '暴雨' }
  const levelOf = (mm) => (mm <= 0 ? 'dry' : mm <= 0.5 ? 'light' : mm <= 2.5 ? 'mid' : mm <= 8 ? 'heavy' : 'storm')
  const rate = (mm) => Math.round(mm * 4 * 10) / 10
  const addMinutes = (hhmm, min) => {
    const [h, m] = hhmm.split(':').map(Number)
    const total = h * 60 + m + min
    return String(Math.floor((((total % 1440) + 1440) % 1440) / 60)).padStart(2, '0') + ':' + String(total % 60).padStart(2, '0')
  }

  /* ---------- hero fragment ---------- */

  const fragRows = $('[data-frag-rows]')
  const fragBig = $('[data-frag-big]')
  const fragK = $('[data-frag-k]')
  const fragThen = $('[data-frag-then]')
  const fragNote = $('[data-frag-note]')
  const fragUpdated = $('[data-frag-updated]')

  let activeDistrict = WX.districts[0].id

  const district = () => WX.districts.find((d) => d.id === activeDistrict) || WX.districts[0]

  function summarise(d) {
    const cells = d.cells
    const wet = cells.filter((c) => c.mm >= 0.05)
    const raining = cells[0].mm >= 0.05
    const peak = wet.reduce((a, b) => (b.mm > a.mm ? b : a), wet[0] || cells[0])
    const lastWet = wet[wet.length - 1]
    const end = lastWet ? addMinutes(lastWet.time, 15) : null
    const nextWet = raining ? null : wet[0]
    return {
      raining,
      peak,
      peakRate: rate(peak.mm),
      end,
      nextWet,
      nextRate: nextWet ? rate(nextWet.mm) : 0,
      dryHours: end ? Math.max(1, Math.round((cells.length * 0.25) - wet.length * 0.25)) : 0,
    }
  }

  function renderHero() {
    const d = district()
    const s = summarise(d)
    fragUpdated.textContent = `${d.updated.slice(0, 5)} 更新`

    if (s.raining) {
      fragK.textContent = '雨停'
      fragBig.textContent = s.end
      fragThen.textContent = `之后 ${s.dryHours} 小时是干的`
      fragNote.textContent = '雨正在下，伞带着；雨停之后再出门也行。'
    } else {
      fragK.textContent = '下一班雨'
      fragBig.textContent = s.nextWet.time
      fragThen.textContent = `${WORDS[levelOf(s.nextRate)]} ${s.nextRate} mm/h`
      fragNote.textContent = '现在没下。出门前再看一眼这张表。'
    }

    const rows = s.raining
      ? [
          ['现在', `正在下 ${WORDS[levelOf(rate(d.cells[0].mm))]}`, `${rate(d.cells[0].mm)} mm/h`],
          [s.peak.time, '雨最大的一格', `${s.peakRate} mm/h`],
          [s.end, '雨停，之后是干的', '无雨'],
        ]
      : [
          ['现在', '没在下', '无雨'],
          [s.nextWet.time, '雨到这条街', `${s.nextRate} mm/h`],
          [addMinutes(s.nextWet.time, 60), '一小时后', '看走势'],
        ]

    fragRows.innerHTML = rows
      .map(
        ([t, label, value], i) => `
        <li><button type="button" aria-pressed="${i === 1}">
          <span class="t">${t}</span><span class="d">${label}</span><span class="v">${value}</span>
        </button></li>`,
      )
      .join('')

    const stripHost = $('[data-frag-strip]')
    if (stripHost) {
      const cells = d.cells.slice(0, 12)
      const max = Math.max(...cells.map((c) => c.mm), 0.4)
      stripHost.innerHTML = cells
        .map((c) => {
          const h = Math.max(8, Math.round((c.mm / max) * 100))
          return `<i class="${c.mm >= 0.05 ? '' : 'dry'}" style="height:${h}%" title="${c.time} ${c.mm}mm"></i>`
        })
        .join('')
    }

    $$('.tab').forEach((b) => b.setAttribute('aria-selected', String(b.dataset.district === activeDistrict)))
  }

  $$('.tab').forEach((tab) => {
    tab.addEventListener('click', () => {
      activeDistrict = tab.dataset.district
      renderHero()
    })
  })

  fragRows.addEventListener('click', (e) => {
    const btn = e.target.closest('button')
    if (!btn) return
    $$('button', fragRows).forEach((b) => b.setAttribute('aria-pressed', 'false'))
    btn.setAttribute('aria-pressed', 'true')
  })

  /* ---------- feature panels ---------- */

  const strip = $('[data-strip]')
  if (strip) {
    const cells = district().cells.slice(0, 12)
    const max = Math.max(...cells.map((c) => c.mm), 0.4)
    strip.innerHTML = cells
      .map((c) => {
        const h = Math.max(6, Math.round((c.mm / max) * 104))
        return `<i class="${c.mm >= 0.05 ? '' : 'dry'}" style="height:${h}px" title="${c.time} ${c.mm}mm"></i>`
      })
      .join('')
  }

  const streets = $('[data-streets]')
  if (streets) {
    streets.innerHTML = WX.districts
      .map((d) => {
        const s = summarise(d)
        return `<div><span>${d.name} · ${d.street}</span><span>${s.raining ? `${s.end} 停` : `${s.nextWet.time} 起`}</span></div>`
      })
      .join('')
  }

  /* ---------- board ---------- */

  const board = $('[data-board]')
  const hours = district().hours
  let openIdx = hours.reduce((best, h, i) => (h.mm > hours[best].mm ? i : best), 0)

  function renderBoard() {
    board.innerHTML = hours
      .map((h, i) => {
        const isNow = i === 0
        const open = i === openIdx
        const detail = `雨量 ${h.mm} 毫米，概率 ${h.prob}%，风 ${h.wind} 公里每小时，气温 ${h.temp} 度。${
          h.mm === 0 ? '这一小时是干的，不用带伞。' : '这一小时有雨，伞带着。'
        }`
        return `
        <li class="row${open ? ' open' : ''}" data-level="${isNow ? 'now' : h.level}">
          <button class="row-top" type="button" aria-expanded="${open}" aria-controls="hour-${i}">
            <span class="row-time">${h.time}</span>
            <span class="row-facts"><span>${h.mm} mm</span><span>概率 ${h.prob}%</span><span>风 ${h.wind} km/h</span></span>
            <span class="row-status">${isNow ? '正在下' : h.word}</span>
          </button>
          <div class="row-detail" id="hour-${i}" ${open ? '' : 'hidden'}>${detail}</div>
        </li>`
      })
      .join('')
  }

  if (board) {
    renderBoard()
    board.addEventListener('click', (e) => {
      const btn = e.target.closest('.row-top')
      if (!btn) return
      const idx = $$('.row', board).indexOf(btn.closest('.row'))
      openIdx = openIdx === idx ? -1 : idx
      renderBoard()
      board.children[openIdx]?.querySelector('.row-top')?.focus({ preventScroll: true })
    })
  }

  const stamp = $('.board-head .stamp')
  if (stamp) stamp.textContent = `${district().updated.slice(0, 5)} 更新 · Open-Meteo · 15 分钟格`

  /* ---------- how it works ---------- */

  const bars = $('[data-state-bars]')
  if (bars) {
    const cells = district().cells.slice(0, 12)
    const max = Math.max(...cells.map((c) => c.mm), 0.4)
    bars.innerHTML = cells
      .map((c) => `<i class="${c.mm >= 0.05 ? '' : 'dry'}" style="height:${Math.max(4, Math.round((c.mm / max) * 100))}%"></i>`)
      .join('')
  }

  const states = $$('[data-state]')
  const statements = $$('[data-statement]')

  function showState(i) {
    states.forEach((s, n) => s.classList.toggle('on', n === i))
    statements.forEach((s, n) => s.classList.toggle('active', n === i))
  }

  statements.forEach((st, i) => st.addEventListener('click', () => showState(i)))

  /* ---------- entrances, shutter, pinned states: one scroll pass ---------- */

  const revealables = [
    ...$$('.section-head'),
    ...$$('.module'),
    ...$$('.board-head'),
    ...$$('.statement'),
    ...$$('.faq-left h2'),
    ...$$('.faq-list details'),
    ...$$('.footer'),
  ]
  const shutters = $$('[data-shutter]')

  if (!reduced) {
    revealables.forEach((el, i) => {
      el.classList.add('reveal')
      el.style.transitionDelay = `${(i % 3) * 70}ms`
    })
  }

  let ticking = false

  function pass() {
    ticking = false
    const vh = window.innerHeight || 800

    for (const el of revealables) {
      if (el.classList.contains('on')) continue
      const r = el.getBoundingClientRect()
      if (r.top < vh * 0.94 && r.bottom > vh * 0.04) el.classList.add('on')
    }
    for (const el of shutters) {
      if (el.classList.contains('on')) continue
      const r = el.getBoundingClientRect()
      if (r.top < vh * 0.92 && r.bottom > 0) el.classList.add('on')
    }
    if (statements.length) {
      const mid = vh / 2
      let best = 0
      let bestD = Infinity
      statements.forEach((s, i) => {
        const r = s.getBoundingClientRect()
        const d = Math.abs(r.top + r.height / 2 - mid)
        if (d < bestD) { bestD = d; best = i }
      })
      showState(best)
    }
  }

  const schedule = () => {
    if (ticking) return
    ticking = true
    requestAnimationFrame(pass)
  }

  window.addEventListener('scroll', schedule, { passive: true })
  window.addEventListener('resize', schedule)
  window.addEventListener('load', schedule)
  schedule()

  renderHero()
  pass()
})()
